  { id: 'official-apply_matrix_arrows', title: 'Apply Matrix Arrows', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\nasync function applyMatrixArrows(scene: Scene) {\n  const plane = new NumberPlane();\n  scene.add(plane);\n\n  const arrow1 = new Arrow({ start: [-2, -1, 0], end: [2, 1, 0], color: YELLOW });\n  const arrow2 = new Arrow({ start: [0, -2, 0], end: [0, 2, 0], color: GREEN_C });\n  const arrow3 = new Arrow({ start: [-1, 1, 0], end: [1, -1, 0], color: RED_C });\n\n  scene.add(arrow1, arrow2, arrow3);\n\n  const label = new Text({ text: \'Before shear\', fontSize: 48, color: \'#ffffff\' });\n  label.moveTo([0, 3.2, 0]);\n  scene.add(label);\n\n  await scene.wait(1);\n\n  // Shear matrix: x\' = x + 0.5*y, y\' = y\n  const shearMatrix = [\n    [1, 0.5, 0],\n    [0, 1, 0],\n    [0, 0, 1],\n  ];\n\n  // Apply the shear to the plane and arrows simultaneously\n  await scene.play(\n    applyMatrix(plane, shearMatrix, { duration: 2 }),\n    applyMatrix(arrow1, shearMatrix, { duration: 2 }),\n    applyMatrix(arrow2, shearMatrix, { duration: 2 }),\n    applyMatrix(arrow3, shearMatrix, { duration: 2 }),\n  );\n\n  // Update label\n  scene.remove(label);\n  const label2 = new Text({\n    text: \'After shear — tips reconstructed\',\n    fontSize: 48,\n    color: \'#ffffff\',\n  });\n  label2.moveTo([0, 3.2, 0]);\n  scene.add(label2);\n\n  await scene.wait(2);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait applyMatrixArrows(scene);\n' },
  { id: 'official-apply_matrix_method', title: 'Apply Matrix Method', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\nasync function applyMatrixMethod(scene: Scene) {\n  const square = new Square({ sideLength: 2, color: BLUE, fillOpacity: 0.5 });\n  scene.add(square);\n  await scene.wait(1);\n\n  // Animate the shear transformation\n  await scene.play(\n    applyMatrix(\n      square,\n      [\n        [1, 0.5, 0],\n        [0, 1, 0],\n        [0, 0, 1],\n      ],\n      { duration: 2 },\n    ),\n  );\n\n  await scene.wait(2);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait applyMatrixMethod(scene);\n' },
  { id: 'official-apply_pointwise_to_center', title: 'Apply Pointwise To Center', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nasync function setupShapes() {\n  scene.clear();\n\n  const circle = new Circle({ radius: 0.8, color: BLUE });\n  circle.moveTo([-3, 0, 0]);\n\n  const square = new Square({ sideLength: 1.4, color: GREEN_C });\n  square.moveTo([0, 0, 0]);\n\n  const triangle = new Triangle({ color: RED_C });\n  triangle.scale(0.8);\n  triangle.moveTo([3, 0, 0]);\n\n  scene.add(circle, square, triangle);\n  await scene.play(\n    new FadeIn(circle, { duration: 0.8 }),\n    new FadeIn(square, { duration: 0.8 }),\n    new FadeIn(triangle, { duration: 0.8 }),\n  );\n  await scene.wait(0.3);\n\n  return { circle, square, triangle };\n}\n\n// Scale each shape around its own center by 1.5x\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.setAttribute(\'disabled\', \'true\');\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.setAttribute(\'disabled\', \'true\');\n\n  const { circle, square, triangle } = await setupShapes();\n\n  const scaleFn = (p: number[]) => [p[0] * 1.5, p[1] * 1.5, p[2]];\n\n  await scene.play(\n    new ApplyPointwiseFunctionToCenter(circle, scaleFn, { duration: 2 }),\n    new ApplyPointwiseFunctionToCenter(square, scaleFn, { duration: 2 }),\n    new ApplyPointwiseFunctionToCenter(triangle, scaleFn, { duration: 2 }),\n  );\n  await scene.wait(1);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.removeAttribute(\'disabled\');\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.removeAttribute(\'disabled\');\n});\n\n// Rotate each shape around its own center by 45 degrees\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.setAttribute(\'disabled\', \'true\');\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.setAttribute(\'disabled\', \'true\');\n\n  const { circle, square, triangle } = await setupShapes();\n\n  const angle = Math.PI / 4; // 45 degrees\n  const rotateFn = (p: number[]) => [\n    p[0] * Math.cos(angle) - p[1] * Math.sin(angle),\n    p[0] * Math.sin(angle) + p[1] * Math.cos(angle),\n    p[2],\n  ];\n\n  await scene.play(\n    new ApplyPointwiseFunctionToCenter(circle, rotateFn, { duration: 2 }),\n    new ApplyPointwiseFunctionToCenter(square, rotateFn, { duration: 2 }),\n    new ApplyPointwiseFunctionToCenter(triangle, rotateFn, { duration: 2 }),\n  );\n  await scene.wait(1);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.removeAttribute(\'disabled\');\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.removeAttribute(\'disabled\');\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', () => {\n  scene.clear();\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.removeAttribute(\'disabled\');\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.removeAttribute(\'disabled\');\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-arg_min', title: 'Arg Min', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  try {\n    scene.clear();\n\n    const ax = new Axes({\n      xRange: [0, 10],\n      yRange: [0, 100, 10],\n      axisConfig: { includeTip: false },\n    });\n    const labels = ax.getAxisLabels({ xLabel: \'x\', yLabel: \'f(x)\' });\n\n    const t = new ValueTracker(0);\n\n    const func = (x) => {\n      return 2 * (x - 5) ** 2;\n    };\n    const graph = ax.plot(func, { color: MAROON });\n\n    const initialPoint = [ax.coordsToPoint(t.getValue(), func(t.getValue()))];\n    const dot = new Dot({ point: initialPoint });\n\n    dot.addUpdater((x) => x.moveTo(ax.coordsToPoint(t.getValue(), func(t.getValue()))));\n    const xSpace = linspace(...ax.xRange.slice(0, 2), 200);\n    const minimumIndex = xSpace.reduce((mi, _, i, a) => (func(a[i]) < func(a[mi]) ? i : mi), 0);\n\n    scene.add(ax, labels, graph, dot);\n    await scene.play(t.animateTo(xSpace[minimumIndex]));\n    await scene.wait();\n  } catch (e) {\n    console.error(\'ERROR:\', e.message, e.stack);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-arrow-dance', title: 'Arrow Dance', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\')!;\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#101319\',\n});\n\nfunction makeArrowTo(radius: number, angle: number): Arrow {\n  return new Arrow({\n    start: [0, 0, 0],\n    end: [radius * Math.cos(angle), radius * Math.sin(angle), 0],\n    color: \'#7dd3fc\',\n    strokeWidth: 3,\n    tipLength: 0.28,\n    tipWidth: 0.12,\n  });\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n\n  scene.clear();\n\n  const n = 12;\n  const radius = 2.6;\n  const arrows: Arrow[] = [];\n\n  for (let i = 0; i < n; i++) {\n    const angle = (2 * Math.PI * i) / n;\n    const arrow = makeArrowTo(radius, angle);\n    arrows.push(arrow);\n  }\n\n  // Grow one-by-one from center out to a 12-gon.\n  // Do not pre-add: GrowArrow/Create pipeline adds to scene.\n  for (const arrow of arrows) {\n    await scene.play(new GrowArrow(arrow, { duration: 0.32 }));\n  }\n\n  await scene.wait(0.25);\n\n  // Shift all arrows outward by +1 unit (together).\n  await scene.play(\n    ...arrows.map((arrow, i) => {\n      const angle = (2 * Math.PI * i) / n;\n      const target = arrow.copy() as Arrow;\n      target.putStartAndEndOn(\n        [Math.cos(angle), Math.sin(angle), 0],\n        [(radius + 1) * Math.cos(angle), (radius + 1) * Math.sin(angle), 0],\n      );\n      return new Transform(arrow, target, { duration: 1.2 });\n    }),\n  );\n\n  // Scale all arrows down to half (together).\n  await scene.play(...arrows.map((arrow) => arrow.animate.scale(0.5).withDuration(0.9)));\n\n  // Change tip color to yellow one after another (staggered).\n  const colorAnimations = arrows.map((arrow) => {\n    const tip = arrow.children[1] as VMobject;\n    return tip.animate.setColor(\'#ffeb3b\').withDuration(0.15);\n  });\n  await scene.play(new AnimationGroup(colorAnimations, { lagRatio: 0.33 }));\n\n  // Rotate each arrow by 180° staggered.\n  const rotateAnimations = arrows.map(\n    (arrow) => new Rotate(arrow, { angle: Math.PI, duration: 0.5 }),\n  );\n  await scene.play(new AnimationGroup(rotateAnimations, { lagRatio: 0.33 }));\n\n  // Final: lay the arrows tangentially around the circle so they point\n  // counter-clockwise around the perimeter (a pinwheel), back in the base color.\n  const perimeterRadius = radius;\n  const arrowLen = 2 * perimeterRadius * Math.sin(Math.PI / n); // chord between neighbours\n  await scene.play(\n    ...arrows.map((arrow, i) => {\n      const angle = (2 * Math.PI * i) / n;\n      const cx = perimeterRadius * Math.cos(angle);\n      const cy = perimeterRadius * Math.sin(angle);\n      const tx = -Math.sin(angle); // unit tangent, counter-clockwise\n      const ty = Math.cos(angle);\n      const half = arrowLen / 2;\n      // Build a FRESH arrow rather than arrow.copy(): by this point each arrow\n      // carries a live group rotation (from the Rotate(π) step), and copy()\n      // inherits it. putStartAndEndOn lays the shaft/tip out in the group-local\n      // frame, so the inherited rotation would be re-applied on top and fling the\n      // shaft to the wrong side. A fresh Arrow has an identity group transform.\n      const target = new Arrow({\n        start: [cx - half * tx, cy - half * ty, 0],\n        end: [cx + half * tx, cy + half * ty, 0],\n        color: \'#7dd3fc\', // reset the yellow tips back to the base arrow color\n        strokeWidth: 3,\n        tipLength: 0.28,\n        tipWidth: 0.12,\n      });\n      return new Transform(arrow, target, { duration: 0.6 });\n    }),\n  );\n\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls and autoplay.\n' },
  { id: 'official-boolean_operations', title: 'Boolean Operations', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\nasync function booleanOperations(scene) {\n  const ellipse1 = new Ellipse({\n    width: 4.0,\n    height: 5.0,\n    fillOpacity: 0.5,\n    color: BLUE,\n    strokeWidth: 2,\n  }).moveTo(LEFT);\n  const ellipse2 = ellipse1.copy().setColor(RED).moveTo(RIGHT);\n  // Large italic underlined title matching Python Manim reference\n  const bool_ops_text = new Text({\n    text: \'Boolean Operation\',\n    fontFamily: \'serif\',\n    fontSize: 48,\n  }).nextTo(ellipse1, UP);\n  const ellipse_group = new Group(bool_ops_text, ellipse1, ellipse2).moveTo(scaleVec(3, LEFT));\n  // Create underline AFTER group is positioned so it uses the text\'s final position\n  const underline = new Underline(bool_ops_text, { color: WHITE, strokeWidth: 2, buff: 0.05 });\n  ellipse_group.add(underline);\n  await scene.play(new FadeIn(ellipse_group));\n\n  // Layout matching Python Manim reference:\n  //        Intersection\n  //  Difference    Union\n  //        Exclusion\n  // Intersection, Union, Exclusion are vertically aligned on the right.\n  // Difference is offset to the left at the same row as Union.\n  // Positions and scales matching Python Manim reference exactly:\n  // Intersection: scale(0.25), move_to(RIGHT*5 + UP*2.5)\n  // Union: scale(0.3), next_to(i, DOWN, buff=text.height*3)\n  // Exclusion: scale(0.3), next_to(u, DOWN, buff=text.height*3.5)\n  // Difference: scale(0.3), next_to(u, LEFT, buff=text.height*3.5)\n  const rightX = 5;\n\n  const i = new Intersection(ellipse1, ellipse2, { color: GREEN, fillOpacity: 0.5 });\n  i.generateTarget();\n  i.targetCopy.scale(0.25).setStrokeWidth(1).moveTo([rightX, 2.5, 0]);\n  await scene.play(new MoveToTarget(i));\n  const intersection_text = new Text({ text: \'Intersection\', fontSize: 23 }).nextTo(i, UP);\n  await scene.play(new FadeIn(intersection_text));\n\n  const u = new Union(ellipse1, ellipse2, { color: ORANGE, fillOpacity: 0.5 });\n  const union_text = new Text({ text: \'Union\', fontSize: 23 });\n  u.generateTarget();\n  u.targetCopy\n    .scale(0.3)\n    .setStrokeWidth(1.2)\n    .nextTo(i, DOWN, union_text.getHeight() * 3);\n  await scene.play(new MoveToTarget(u));\n  union_text.nextTo(u, UP);\n  await scene.play(new FadeIn(union_text));\n\n  const e = new Exclusion(ellipse1, ellipse2, { color: YELLOW, fillOpacity: 0.5 });\n  const exclusion_text = new Text({ text: \'Exclusion\', fontSize: 23 });\n  e.generateTarget();\n  e.targetCopy\n    .scale(0.3)\n    .setStrokeWidth(1.2)\n    .nextTo(u, DOWN, exclusion_text.getHeight() * 3.5);\n  await scene.play(new MoveToTarget(e));\n  exclusion_text.nextTo(e, UP);\n  await scene.play(new FadeIn(exclusion_text));\n\n  const d = new Difference(ellipse1, ellipse2, { color: PINK, fillOpacity: 0.5 });\n  const difference_text = new Text({ text: \'Difference\', fontSize: 23 });\n  d.generateTarget();\n  d.targetCopy\n    .scale(0.3)\n    .setStrokeWidth(1.2)\n    .nextTo(u, LEFT, difference_text.getHeight() * 3.5);\n  await scene.play(new MoveToTarget(d));\n  difference_text.nextTo(d, UP);\n  await scene.play(new FadeIn(difference_text));\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait booleanOperations(scene);\n' },
  { id: 'official-brace_annotation', title: 'Brace Annotation', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\nasync function braceAnnotation(scene: Scene) {\n  const dot = new Dot({ point: [-2, -1, 0] });\n  const dot2 = new Dot({ point: [2, 1, 0] });\n  const line = new Line({ start: dot.getCenter(), end: dot2.getCenter() }).setColor(ORANGE);\n  const b1 = new Brace(line);\n  const b1text = b1.getText(\'Horizontal distance\');\n  const b2 = new Brace(line, {\n    direction: line\n      .copy()\n      .rotate(Math.PI / 2)\n      .getUnitVector(),\n  });\n  const b2text = b2.getTex(\'x-x_1\', { fontSize: 48 });\n  scene.add(line, dot, dot2, b1, b2, b1text, b2text);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait braceAnnotation(scene);\n' },
  { id: 'official-clickable_objects', title: 'Clickable Objects', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\n// Colors the clickable circle cycles through on each click.\nconst PALETTE = [BLUE, GREEN, YELLOW, RED, PURPLE, ORANGE, TEAL, PINK];\n\n// Interaction handles are disposed before each replay so their canvas/window\n// event listeners don\'t accumulate across runs.\nlet handles: Array<{ dispose: () => void }> = [];\n\nfunction disposeHandles(): void {\n  handles.forEach((h) => h.dispose());\n  handles = [];\n}\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  try {\n    disposeHandles();\n    scene.clear();\n\n    const title = new Text({\n      text: \'Click the circle  •  Drag the square\',\n      fontSize: 26,\n      color: WHITE,\n    });\n    title.moveTo([0, 2.8, 0]);\n\n    // --- Clickable: a discrete tap action. The circle never moves. ---\n    let colorIndex = 0;\n    let clickCount = 0;\n\n    const circle = new Circle({ radius: 0.7, color: BLUE, fillOpacity: 0.9 });\n    circle.moveTo([-2.5, 0.3, 0]);\n\n    const counter = new Text({ text: \'Clicks: 0\', fontSize: 22, color: WHITE });\n    counter.moveTo([-2.5, -1.6, 0]);\n\n    // --- Draggable: a continuous gesture that repositions the square. ---\n    const square = new Square({ sideLength: 1.3, color: GREEN, fillOpacity: 0.9 });\n    square.moveTo([2.5, 0.3, 0]);\n\n    const posLabel = new Text({ text: \'Square: (2.5, 0.3)\', fontSize: 22, color: WHITE });\n    posLabel.moveTo([2.5, -1.6, 0]);\n\n    const hint = new Text({\n      text: \'Double-click the circle to reset\',\n      fontSize: 18,\n      color: \'#888888\',\n    });\n    hint.moveTo([0, -2.8, 0]);\n\n    scene.add(title, circle, counter, square, posLabel, hint);\n    scene.render();\n\n    // Click → cycle color and bump the counter (the object stays put).\n    // Double-click → reset to the initial state. Reset is idempotent because\n    // browsers fire `click` events before `dblclick`.\n    // This scene has no animation loop, so interaction callbacks must call\n    // scene.render() to repaint after they mutate a mobject.\n    handles.push(\n      makeClickable(circle, scene, {\n        onClick: () => {\n          clickCount += 1;\n          colorIndex = (colorIndex + 1) % PALETTE.length;\n          circle.setColor(PALETTE[colorIndex]);\n          counter.setText(`Clicks: ${clickCount}`);\n          scene.render();\n        },\n        onDoubleClick: () => {\n          clickCount = 0;\n          colorIndex = 0;\n          circle.setColor(BLUE);\n          counter.setText(\'Clicks: 0\');\n          scene.render();\n        },\n      }),\n    );\n\n    // Drag → reposition the square and reflect its live position in the label.\n    handles.push(\n      makeDraggable(square, scene, {\n        onDrag: (_mobject, position: Vector3Tuple) => {\n          posLabel.setText(`Square: (${position[0].toFixed(1)}, ${position[1].toFixed(1)})`);\n          scene.render();\n        },\n      }),\n    );\n  } catch (e) {\n    console.error(\'ERROR:\', e.message, e.stack);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  disposeHandles();\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-displaying_equations', title: 'Displaying Equations', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const FONT_URL = \'./fonts/KaTeX_Main-Regular.ttf\';\n  const firstLine = new Text({\n    text: \'Manim also allows you\',\n    fontSize: 36,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const secondLine = new Text({\n    text: \'to show beautiful math equations\',\n    fontSize: 36,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const equation = new MathTexImage({\n    latex: \'d(p, q) = \\\\sqrt{\\\\sum_{i=1}^n (q_i - p_i)^2}\',\n    fontSize: 48,\n    color: WHITE,\n  });\n\n  await Promise.all([firstLine.loadGlyphs(), secondLine.loadGlyphs()]);\n  secondLine.nextTo(firstLine, DOWN);\n\n  await equation.waitForRender();\n\n  await scene.play(new Write(firstLine), new Write(secondLine));\n  await scene.wait(1);\n  await scene.play(new ReplacementTransform(firstLine, equation), new FadeOut(secondLine));\n  await scene.wait(3);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-displaying_text', title: 'Displaying Text', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const FONT_URL = \'./fonts/KaTeX_Main-Regular.ttf\';\n  const firstLine = new Text({\n    text: \'Create cool animations\',\n    fontSize: 48,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const secondLine = new Text({\n    text: \'using Manim\',\n    fontSize: 48,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const thirdLine = new Text({ text: \'Try it out yourself.\', fontSize: 48, color: RED });\n\n  await Promise.all([firstLine.loadGlyphs(), secondLine.loadGlyphs()]);\n  secondLine.nextTo(firstLine, DOWN);\n\n  await scene.wait(1);\n  await scene.play(new Write(firstLine), new Write(secondLine));\n  await scene.wait(1);\n\n  // Cross-fade: fade out first line while fading in third line at same position\n  scene.add(thirdLine);\n  thirdLine.opacity = 0;\n  await scene.play(\n    new AnimationGroup([\n      new FadeOut(firstLine, { duration: 1.5, rateFunc: smooth }),\n      new FadeIn(thirdLine, { duration: 1.5, rateFunc: smooth }),\n      new FadeOut(secondLine, { duration: 1.5, rateFunc: smooth }),\n    ]),\n  );\n  await scene.wait(2);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-draggable_objects', title: 'Draggable Objects', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  try {\n    scene.clear();\n\n    // Create draggable objects\n    const circle = new Circle({ radius: 0.5, color: BLUE, fillOpacity: 0.8 });\n    circle.moveTo([-2, 1, 0]);\n\n    const square = new Square({ sideLength: 0.8, color: GREEN, fillOpacity: 0.8 });\n    square.moveTo([2, 1, 0]);\n\n    const dot = new Dot({ color: YELLOW, radius: 0.15 });\n    dot.moveTo([0, -1, 0]);\n\n    // A line that connects the circle and dot, updating in real time.\n    // Updaters only run during play()/wait() loops, so rebuild the line\n    // from onDrag instead — Draggable re-renders after each onDrag.\n    const line = new Line({ start: circle.getCenter(), end: dot.getCenter() }).setColor(RED);\n    const updateLine = () => {\n      line.become(new Line({ start: circle.getCenter(), end: dot.getCenter() }).setColor(RED));\n    };\n\n    // Label\n    const label = new Text({ text: \'Drag the shapes!\', fontSize: 24, color: WHITE });\n    label.moveTo([0, 2.5, 0]);\n\n    scene.add(circle, square, dot, line, label);\n    scene.render();\n\n    // Make objects draggable\n    makeDraggable(circle, scene, { onDrag: updateLine });\n    makeDraggable(dot, scene, { onDrag: updateLine });\n\n    // Square is constrained to X axis only\n    makeDraggable(square, scene, {\n      constrainY: [1, 1],\n      snapToGrid: 0.5,\n    });\n  } catch (e) {\n    console.error(\'ERROR:\', e.message, e.stack);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-easing_functions_showcase', title: 'Easing Functions Showcase', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n// Rate functions to compare, each with a label and color\nconst rateFunctions: Array<{\n  name: string;\n  rateFunc: (t: number) => number;\n  color: string;\n}> = [\n  { name: \'smooth\', rateFunc: smooth, color: BLUE },\n  { name: \'easeInOutSine\', rateFunc: easeInOutSine, color: RED },\n  { name: \'easeInOutBack\', rateFunc: easeInOutBack, color: GREEN },\n  { name: \'easeOutElastic\', rateFunc: easeOutElastic, color: YELLOW },\n  { name: \'easeOutBounce\', rateFunc: easeOutBounce, color: PURPLE },\n  { name: \'easeInOutCirc\', rateFunc: easeInOutCirc, color: ORANGE },\n  { name: \'smoothstep\', rateFunc: smoothstep, color: \'#ff69b4\' },\n  { name: \'easeInOutExpo\', rateFunc: easeInOutExpo, color: \'#00ced1\' },\n];\n\nconst ROW_COUNT = rateFunctions.length;\nconst TOP_Y = 3.0;\nconst ROW_SPACING = 0.75;\nconst START_X = -1.2;\nconst SHIFT_DISTANCE = 5.5;\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const dots: Dot[] = [];\n  const shiftDirection = scaleVec(SHIFT_DISTANCE, RIGHT) as [number, number, number];\n\n  for (let i = 0; i < ROW_COUNT; i++) {\n    const y = TOP_Y - i * ROW_SPACING;\n    const { name, color } = rateFunctions[i];\n\n    // Track line (faint guide)\n    const trackLine = new Line({\n      start: [START_X, y, 0],\n      end: [START_X + SHIFT_DISTANCE, y, 0],\n      color: \'#333333\',\n      strokeWidth: 1,\n    });\n\n    // Label on the left, right-edge aligned just before track start\n    const label = new Text({\n      text: name,\n      fontSize: 26,\n      color: WHITE,\n    });\n    label.nextTo(trackLine, LEFT, 0.2);\n\n    // Dot at the start position\n    const dot = new Dot({\n      point: [START_X, y, 0],\n      radius: 0.1,\n      color,\n    });\n\n    scene.add(label, trackLine, dot);\n    dots.push(dot);\n  }\n\n  // Build simultaneous shift animations with different rate functions\n  const animations = dots.map(\n    (dot, i) =>\n      new Shift(dot, {\n        direction: shiftDirection,\n        duration: 3,\n        rateFunc: rateFunctions[i].rateFunc,\n      }),\n  );\n\n  await scene.play(new AnimationGroup(animations));\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-export_animation', title: 'Export Animation', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\')!;\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nconst progressContainer = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!;\nconst progressFill = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!;\nconst progressText = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!;\n\nfunction showProgress(progress: number, label: string) {\n  progressContainer.style.display = \'block\';\n  progressFill.style.width = `${Math.round(progress * 100)}%`;\n  progressText.textContent = `${label} — ${Math.round(progress * 100)}%`;\n}\n\nfunction hideProgress() {\n  progressContainer.style.display = \'none\';\n  progressFill.style.width = \'0%\';\n}\n\nfunction setButtonsDisabled(disabled: boolean) {\n  document\n    .querySelectorAll<HTMLButtonElement>(\'.controls button\')\n    .forEach((btn) => (btn.disabled = disabled));\n}\n\n// Build the same three animations Play and Export share.\n// Each call returns a fresh set against a freshly populated scene\n// — animations are stateful (begin() snapshots opacities), so reusing\n// instances across runs would replay against stale state.\nfunction buildAnimations(): Animation[] {\n  scene.clear();\n  const square = new Square({ sideLength: 2.5, color: BLUE, fillOpacity: 0.5 });\n  const circle = new Circle({ radius: 1.25, color: GREEN, fillOpacity: 0.5 });\n  return [\n    new Create(square, { duration: 1 }),\n    new Transform(square, circle, { duration: 1 }),\n    new FadeOut(square, { duration: 1 }),\n  ];\n}\n\n// Wire animations into the scene\'s timeline sequentially without\n// starting playback. We avoid Succession here because it would call\n// begin() on every child up front — Transform.begin() would then\n// snapshot the fillOpacity that Create.begin() just zeroed, leaving\n// the square invisible after the morph. Timeline drives each begin()\n// lazily inside _updateAnimationsAtTime as forward-seeking crosses\n// each animation\'s start time, which is what GifExporter does.\nfunction installTimeline(anims: Animation[]): number {\n  scene.add(anims[0].mobject);\n  const timeline = new Timeline();\n  for (const anim of anims) timeline.add(anim, \'>\');\n  scene.setTimeline(timeline);\n  return timeline.getDuration();\n}\n\n// Play animation\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n\n  setButtonsDisabled(true);\n\n  for (const anim of buildAnimations()) {\n    await scene.play(anim);\n  }\n\n  setButtonsDisabled(false);\n});\n\n// Export GIF\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n\n  setButtonsDisabled(true);\n\n  try {\n    const duration = installTimeline(buildAnimations());\n    await scene.export(\'animation.gif\', {\n      fps: 15,\n      quality: 10,\n      duration,\n      onProgress: (p) => showProgress(p, \'Exporting GIF\'),\n    });\n  } catch (err) {\n    console.error(\'GIF export failed:\', err);\n  } finally {\n    hideProgress();\n\n    setButtonsDisabled(false);\n  }\n});\n\n// Export WebM\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n\n  setButtonsDisabled(true);\n\n  try {\n    const duration = installTimeline(buildAnimations());\n    await scene.export(\'animation.webm\', {\n      fps: 30,\n      duration,\n      onProgress: (p) => showProgress(p, \'Exporting WebM\'),\n    });\n  } catch (err) {\n    console.error(\'WebM export failed:\', err);\n  } finally {\n    hideProgress();\n\n    setButtonsDisabled(false);\n  }\n});\n\n// Reset\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-fixed_in_frame_mobject_test', title: 'Fixed In Frame Mobject Test', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 75 * (Math.PI / 180),\n  theta: -45 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  orbitControlsUp: \'z\',\n});\n\nasync function fixedInFrameMObjectTest(scene: ThreeDScene) {\n  const axes = new ThreeDAxes({\n    xRange: [-6, 6, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-4, 4, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.3,\n    tipRadius: 0.12,\n    shaftRadius: 0.008,\n  });\n  const text3d = new Text({ text: \'This is a 3D text\' });\n  scene.addFixedInFrameMobjects(text3d);\n  text3d.toCorner(UL);\n  scene.add(axes);\n  await scene.wait(999999);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait fixedInFrameMObjectTest(scene);\n' },
  { id: 'official-fixed_orientation_follow', title: 'Fixed Orientation Follow', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: "\n\nfunction addVectors(a: number[], b: number[]): [number, number, number] {\n  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];\n}\n\nfunction scalarMult(a: number[], b: number): [number, number, number] {\n  return [a[0] * b, a[1] * b, a[2] * b];\n}\n\nconst container = document.getElementById('container')!;\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: '#191919',\n  phi: 75 * (Math.PI / 180),\n  theta: -45 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  enableOrbitControls: true,\n  orbitControlsUp: 'z',\n});\n\nconst axes = new ThreeDAxes({\n  xRange: [-5, 5, 1],\n  yRange: [-5, 5, 1],\n  zRange: [-5, 5, 1],\n  xLength: 10,\n  yLength: 10,\n  zLength: 10,\n  showLabels: true,\n});\n\nconst dot = new Dot3D({ radius: 0.1 }).moveTo(axes.coordsToPoint(1, 1, 1));\nmakeDraggable(dot, scene);\n\nconst lbl = new MathTex({ latex: 'r', fontSize: 0.2 }).addUpdater((mob) => {\n  mob.moveTo(addVectors(dot.getCenter(), scalarMult(UP, 0.15)));\n});\n\nscene.add(axes, dot, lbl);\nscene.addFixedOrientationMobjects(lbl);\n\nawait scene.wait(999999);\n" },
  { id: 'official-fixed_orientation_mobjects', title: 'Fixed Orientation Mobjects', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 75 * (Math.PI / 180),\n  theta: -45 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  orbitControlsUp: \'z\',\n});\n\nasync function fixedOrientationMobjectsExample(scene: ThreeDScene) {\n  const axes = new ThreeDAxes({\n    xRange: [-6, 6, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-4, 4, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.3,\n    tipRadius: 0.12,\n    shaftRadius: 0.008,\n  });\n\n  // Create a label that sits in 3D space but always faces the camera.\n  // Small XY offset + GOLD tint so the text reads against the white axis lines\n  // without floating away from the origin it labels.\n  const label = new Text({ text: \'Origin\', fontSize: 32, color: GOLD });\n  label.moveTo([0.4, 0.4, 0.3]);\n\n  const xLabel = new Text({ text: \'X\', fontSize: 32, color: GOLD });\n  xLabel.moveTo([6.8, 0, 0.4]);\n\n  scene.add(axes, label, xLabel);\n\n  // Make the labels always face the camera regardless of orbit angle\n  scene.addFixedOrientationMobjects(label, xLabel);\n\n  // Rotate the camera so the billboard effect is visible\n  scene.beginAmbientCameraRotation(0.3);\n  await scene.wait(999999);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait fixedOrientationMobjectsExample(scene);\n' },
  { id: 'official-following_graph_camera', title: 'Following Graph Camera', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\nasync function followingGraphCamera(scene: Scene) {\n  // Save camera frame state\n  scene.camera.frame.saveState();\n\n  // Create the axes and the curve\n  const ax = new Axes({ xRange: [-1, 10], yRange: [-1, 10] });\n  const graph = ax.plot((x) => Math.sin(x), { color: BLUE, xRange: [0, 3 * Math.PI] });\n\n  // Create dots based on the graph\n  const movingDot = new Dot({ point: ax.i2gp(graph.tMin, graph), color: ORANGE });\n  const dot1 = new Dot({ point: ax.i2gp(graph.tMin, graph) });\n  const dot2 = new Dot({ point: ax.i2gp(graph.tMax, graph) });\n\n  scene.add(ax, graph, dot1, dot2, movingDot);\n\n  // Zoom camera to 0.5x and center on moving dot\n  scene.camera.frame.generateTarget();\n  scene.camera.frame.targetCopy.scale(0.5);\n  scene.camera.frame.targetCopy.moveTo(movingDot.getCenter());\n  await scene.play(new MoveToTarget(scene.camera.frame));\n\n  // Add updater so camera follows the moving dot\n  const updateCurve = (mob) => {\n    mob.moveTo(movingDot.getCenter());\n  };\n  scene.camera.frame.addUpdater(updateCurve);\n\n  // Animate dot moving along the graph path\n  await scene.play(new MoveAlongPath(movingDot, { path: graph, rateFunc: linear }));\n\n  // Remove updater and restore camera to original state\n  scene.camera.frame.removeUpdater(updateCurve);\n  await scene.play(new Restore(scene.camera.frame));\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait followingGraphCamera(scene);\n' },
  { id: 'official-graph_area_plot', title: 'Graph Area Plot', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '// Converted from Python Manim → ManimWeb TypeScript\n// Review and adjust as needed — automated conversion is approximate.\n\n\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 854,\n  height: 480,\n  backgroundColor: BLACK,\n});\n\nasync function graphAreaPlot(scene) {\n  const ax = new Axes({\n    xRange: [0, 5],\n    yRange: [0, 6],\n    xAxisConfig: { numbersToInclude: [2, 3] },\n    tips: false,\n  });\n  const labels = ax.getAxisLabels();\n\n  const curve1 = ax.plot((x) => 4 * x - Math.pow(x, 2), { xRange: [0, 4], color: BLUE_C });\n  const curve2 = ax.plot((x) => 0.8 * Math.pow(x, 2) - 3 * x + 4, {\n    xRange: [0, 4],\n    color: GREEN_B,\n  });\n\n  const line1 = ax.getVerticalLine(ax.inputToGraphPoint(2, curve1), { color: YELLOW });\n  const line2 = ax.getVerticalLine(ax.i2gp(3, curve1), { color: YELLOW });\n\n  const riemannArea = ax.getRiemannRectangles(curve1, {\n    xRange: [0.3, 0.6],\n    dx: 0.03,\n    color: BLUE,\n    fillOpacity: 0.5,\n  });\n  const area = ax.getArea(curve2, [2, 3], { boundedGraph: curve1, color: GRAY, opacity: 0.5 });\n\n  scene.add(ax, labels, curve1, curve2, line1, line2, riemannArea, area);\n}\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait graphAreaPlot(scene);\n' },
  { id: 'official-heat_diagram_plot', title: 'Heat Diagram Plot', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '// Converted from Python Manim → ManimWeb TypeScript\n// Original: HeatDiagramPlot example from Manim Community docs\n\n\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const ax = new Axes({\n    xRange: [0, 40, 5],\n    yRange: [-8, 32, 5],\n    xLength: 9,\n    yLength: 6,\n    xAxisConfig: { numbersToInclude: [0, 5, 10, 15, 20, 25, 30, 35] },\n    yAxisConfig: { numbersToInclude: [-5, 0, 5, 10, 15, 20, 25, 30] },\n    tips: false,\n  });\n\n  // Create Tex labels and wait for rendering\n  const xLabel = new Tex({ latex: \'$\\\\Delta Q$\', fontSize: 0.4 });\n  const yLabel = new Tex({ latex: \'T[$^\\\\circ C$]\', fontSize: 0.4 });\n  await xLabel.waitForRender();\n  await yLabel.waitForRender();\n\n  const labels = ax.getAxisLabels({ xLabel, yLabel });\n\n  const xVals = [0, 8, 38, 39];\n  const yVals = [20, 0, 0, -5];\n  const graph = ax.plotLineGraph({ xValues: xVals, yValues: yVals });\n\n  scene.add(ax, labels, graph);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Auto-play on load\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).click();\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-manim_ce_logo', title: 'Manim Ce Logo', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#ece6e2\',\n});\n\nasync function manimCELogo(scene: Scene) {\n  const logoGreen = \'#87c2a5\';\n  const logoBlue = \'#525893\';\n  const logoRed = \'#e07a5f\';\n  const logoBlack = \'#343434\';\n  const dsM = new MathTexImage({ latex: \'\\\\mathbb{M}\', fillColor: logoBlack });\n  await dsM.waitForRender();\n  dsM.scale(7);\n  dsM.shift(addVec(scaleVec(2.25, LEFT), scaleVec(1.5, UP)));\n  const circle = new Circle({ color: logoGreen, fillOpacity: 1 }).shift(LEFT);\n  const square = new Square({ color: logoBlue, fillOpacity: 1 }).shift(UP);\n  const triangle = new Triangle({ color: logoRed, fillOpacity: 1 }).shift(RIGHT);\n  const logo = new VGroup(triangle, square, circle, dsM);\n  logo.moveTo(ORIGIN);\n  scene.add(logo);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait manimCELogo(scene);\n' },
  { id: 'official-manim_examples', title: 'Manim Examples', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst TAU = Math.PI * 2;\nconst FONT_URL = \'./fonts/KaTeX_Main-Regular.ttf\';\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nconst buttons = document.querySelectorAll(\'button\');\n\nfunction setAnimating(state) {\n\n  buttons.forEach((b) => (b.disabled = state));\n}\n\n// Demo 1: Square to Circle\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', async () => {\n\n  setAnimating(true);\n  scene.clear();\n\n  const circle = new Circle({ radius: 1.5 });\n  const square = new Square({ sideLength: 3 });\n\n  await scene.play(new Create(square));\n  await scene.play(new Transform(square, circle));\n  await scene.play(new FadeOut(square));\n\n  setAnimating(false);\n});\n\n// Demo 2: Square to Circle with Modifications\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', async () => {\n\n  setAnimating(true);\n  scene.clear();\n\n  const circle = new Circle({ radius: 1.5, fillColor: PINK, fillOpacity: 0.5 });\n  const square = new Square({ sideLength: 3 });\n\n  square.flip(RIGHT);\n  square.rotate((-3 * TAU) / 8);\n\n  await scene.play(new Create(square));\n  await scene.play(new Transform(square, circle));\n  await scene.play(new FadeOut(square));\n\n  setAnimating(false);\n});\n\n// Demo 3: Displaying Text\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', async () => {\n\n  setAnimating(true);\n  scene.clear();\n\n  const firstLine = new Text({\n    text: \'Create cool animations\',\n    fontSize: 48,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const secondLine = new Text({\n    text: \'using Manim\',\n    fontSize: 48,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const thirdLine = new Text({ text: \'Try it out yourself.\', fontSize: 48, color: RED });\n\n  await Promise.all([firstLine.loadGlyphs(), secondLine.loadGlyphs()]);\n  secondLine.nextTo(firstLine, DOWN);\n\n  await scene.wait(1);\n  await scene.play(new Write(firstLine), new Write(secondLine));\n  await scene.wait(1);\n\n  // Cross-fade: fade out first line while fading in third line at same position\n  scene.add(thirdLine);\n  thirdLine.opacity = 0;\n  await scene.play(\n    new AnimationGroup([\n      new FadeOut(firstLine, { duration: 1.5, rateFunc: smooth }),\n      new FadeIn(thirdLine, { duration: 1.5, rateFunc: smooth }),\n      new FadeOut(secondLine, { duration: 1.5, rateFunc: smooth }),\n    ]),\n  );\n  await scene.wait(2);\n\n  setAnimating(false);\n});\n\n// Demo 4: Math Equations\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', async () => {\n\n  setAnimating(true);\n  scene.clear();\n\n  const firstLine = new Text({\n    text: \'Manim also allows you\',\n    fontSize: 36,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const secondLine = new Text({\n    text: \'to show beautiful math equations\',\n    fontSize: 36,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  const equation = new MathTexImage({\n    latex: \'d(p, q) = \\\\sqrt{\\\\sum_{i=1}^n (q_i - p_i)^2}\',\n    fontSize: 48,\n    color: WHITE,\n  });\n\n  await Promise.all([firstLine.loadGlyphs(), secondLine.loadGlyphs()]);\n  secondLine.nextTo(firstLine, DOWN);\n\n  await equation.waitForRender();\n\n  await scene.play(new Write(firstLine), new Write(secondLine));\n  await scene.wait(1);\n  await scene.play(new ReplacementTransform(firstLine, equation), new FadeOut(secondLine));\n  await scene.wait(3);\n\n  setAnimating(false);\n});\n\n// Demo 5: Function Graph\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', async () => {\n\n  setAnimating(true);\n  scene.clear();\n\n  const axes = new Axes({\n    xRange: [-3, 3, 1],\n    yRange: [-5, 5, 1],\n    xLength: 8,\n    yLength: 6,\n    color: BLUE,\n    tips: true,\n  });\n\n  const graph = new FunctionGraph({\n    func: (x) => x * x,\n    xRange: [-2.2, 2.2],\n    color: WHITE,\n    axes: axes,\n  });\n\n  const graphLabel = new MathTexImage({ latex: \'x^2\', fontSize: 32, color: WHITE });\n  graphLabel.shift([4.5, 2, 0]);\n\n  const graph2 = new FunctionGraph({\n    func: (x) => x * x * x,\n    xRange: [-1.7, 1.7],\n    color: WHITE,\n    axes: axes,\n  });\n\n  const graphLabel2 = new MathTexImage({ latex: \'x^3\', fontSize: 32, color: WHITE });\n  graphLabel2.shift([4.5, 2, 0]);\n\n  await graphLabel.waitForRender();\n  await graphLabel2.waitForRender();\n\n  await scene.play(new Create(axes), new Create(graph), new FadeIn(graphLabel));\n  await scene.wait(1);\n  await scene.play(new Transform(graph, graph2), new Transform(graphLabel, graphLabel2));\n  await scene.wait(1);\n\n  setAnimating(false);\n});\n\n// Run first demo on load\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).click();\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-mathtex_number_morph', title: 'Mathtex Number Morph', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 1400,\n  height: 720,\n  backgroundColor: BLACK,\n});\n\nasync function numberMorphDemo(scene: Scene) {\n  const duration = 2.5;\n  const fontSize = 120;\n  const spacing = 1.5;\n\n  const pairs: Array<{ start: MathTex; target: MathTex }> = [];\n  for (let n = 0; n <= 8; n++) {\n    const start = new MathTex({\n      latex: String(n),\n      color: WHITE,\n      fillOpacity: 1,\n      fontSize,\n    });\n    const target = new MathTex({\n      latex: String(n + 1),\n      color: WHITE,\n      fillOpacity: 1,\n      fontSize,\n    });\n    pairs.push({ start, target });\n  }\n\n  await Promise.all(\n    pairs.flatMap(({ start, target }) => [start.waitForRender(), target.waitForRender()]),\n  );\n\n  const cols = 3;\n  const xStart = -spacing;\n  const yStart = spacing;\n\n  pairs.forEach(({ start, target }, i) => {\n    const row = Math.floor(i / cols);\n    const col = i % cols;\n    const pos: [number, number, number] = [xStart + col * spacing, yStart - row * spacing, 0];\n    start.moveTo(pos);\n    target.moveTo(pos);\n    scene.add(start);\n  });\n\n  for (const { start, target } of pairs) {\n    await scene.play(new Transform(start, target, { duration }));\n  }\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })?.addEventListener(\'click\', async () => {\n\n  const playBtn = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }) | null;\n  if (playBtn) playBtn.disabled = true;\n\n  scene.clear();\n  await numberMorphDemo(scene);\n\n  if (playBtn) playBtn.disabled = false;\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })?.addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait numberMorphDemo(scene);\n' },
  { id: 'official-mathtex_scale_before_render', title: 'Mathtex Scale Before Render', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: "/**\n * Issue #324 demo: `MathTex.scale(...)` was a silent no-op when called before\n * `await waitForRender()`, because `VGroup.scale` iterated children and the\n * glyphs were not rendered yet. After the fix the pre-render scale is recorded\n * on the group's own `scaleVector` and applied via Three.js once glyphs\n * materialize, with no explicit await required.\n *\n * The orange `x^2` is built with `scale(2)` before being added to the scene\n * and should render at twice the size of the blue baseline.\n */\n\n\nconst container = document.getElementById('container');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nconst baseline = new MathTex({ latex: 'x^2', color: '#6aa9ff' });\nbaseline.moveTo([-2, 0, 0]);\n\nconst scaled = new MathTex({ latex: 'x^2', color: '#ffaa66' });\nscaled.scale(2);\nscaled.moveTo([2, 0, 0]);\n\nscene.add(baseline);\nawait scene.play(new Create(scaled));\n" },
  { id: 'official-mathtex_shift_before_render', title: 'Mathtex Shift Before Render', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: "/**\n * Issue #318 demo: `MathTex.shift(...)` (and any transform that delegates to it)\n * used to be a silent no-op when called before `await waitForRender()`, because\n * `VGroup.shift` iterated children and the glyphs were not rendered yet. After\n * the fix, the pre-render shift is recorded on the group's own `position` and\n * the glyphs render at the expected location without an explicit await.\n */\n\n\nconst container = document.getElementById('container');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n// Three labels, each constructed and shifted to its slot BEFORE any render.\n// Pre-fix: all three would have collapsed to the origin on top of each other.\nconst left = new MathTex({ latex: '0', color: WHITE, fontSize: 64 });\nleft.shift([-4, 0, 0]);\n\nconst middle = new MathTex({ latex: '\\\\pi', color: GOLD, fontSize: 64 });\nmiddle.moveTo([0, 1.5, 0]); // moveTo also delegates to shift internally\n\nconst right = new MathTex({ latex: '\\\\infty', color: RED, fontSize: 64 });\nright.shift([4, -1.5, 0]);\n\nscene.add(left, middle, right);\n" },
  { id: 'official-mathtex_stroke_zero', title: 'Mathtex Stroke Zero', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 900,\n  height: 500,\n  backgroundColor: BLACK,\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })?.addEventListener(\'click\', async () => {\n\n  const playBtn = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }) | null;\n  if (playBtn) playBtn.disabled = true;\n\n  scene.clear();\n\n  const eqStrokeZero = new MathTex({\n    latex: \'\\\\text{strokeWidth}=0:\\\\quad e^{i\\\\pi}+1=0\',\n    color: WHITE,\n    strokeWidth: 0,\n    fillOpacity: 1,\n  });\n\n  const eqTinyStroke = new MathTex({\n    latex: \'\\\\text{strokeWidth}=0.01:\\\\quad e^{i\\\\pi}+1=0\',\n    color: YELLOW,\n    strokeWidth: 0.01,\n    fillOpacity: 1,\n  });\n\n  await Promise.all([eqStrokeZero.waitForRender(), eqTinyStroke.waitForRender()]);\n\n  eqTinyStroke.nextTo(eqStrokeZero, DOWN, 0.8);\n\n  await scene.play(new FadeIn(eqStrokeZero), new FadeIn(eqTinyStroke));\n\n  if (playBtn) playBtn.disabled = false;\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })?.addEventListener(\'click\', () => {\n  scene.clear();\n});\n' },
  { id: 'official-mathtex_svg', title: 'Mathtex Svg', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nasync function mathtexSvgDemo(scene: Scene) {\n  // Pre-create all equations\n  const equation1 = new MathTex({\n    latex: \'\\\\int_0^\\\\infty e^{-x^2} dx = \\\\frac{\\\\sqrt{\\\\pi}}{2}\',\n    color: WHITE,\n  });\n  const equation2 = new MathTex({\n    latex: \'e^{i\\\\pi} + 1 = 0\',\n    color: GOLD,\n  });\n  const multiPart = new MathTex({\n    latex: [\'E\', \'=\', \'mc^2\'],\n    color: WHITE,\n  });\n  const equation3 = new MathTex({\n    latex: \'\\\\sum_{k=1}^{n} k = \\\\frac{n(n+1)}{2}\',\n    color: GREEN,\n  });\n  const matrix = new MathTex({\n    latex: \'A = \\\\begin{pmatrix} a_{11} & a_{12} \\\\\\\\ a_{21} & a_{22} \\\\end{pmatrix}\',\n    color: WHITE,\n  });\n\n  // Equations for transform demos\n  const pythagoras = new MathTex({\n    latex: \'a^2 + b^2 = c^2\',\n    color: WHITE,\n  });\n  const pythagorasExpanded = new MathTex({\n    latex: \'c = \\\\sqrt{a^2 + b^2}\',\n    color: TEAL,\n  });\n  const scalingEq = new MathTex({\n    latex: \'\\\\nabla \\\\cdot \\\\mathbf{E} = \\\\frac{\\\\rho}{\\\\epsilon_0}\',\n    color: GREEN,\n  });\n  const shiftingEq = new MathTex({\n    latex: \'\\\\lim_{x \\\\to \\\\infty} f(x)\',\n    color: RED,\n  });\n  const rotatingEq = new MathTex({\n    latex: \'\\\\frac{\\\\partial f}{\\\\partial x}\',\n    color: BLUE,\n  });\n  const textBefore = new MathTex({\n    latex: \'x = 1\',\n    color: WHITE,\n  });\n  const textAfter = new MathTex({\n    latex: \'x = 42\',\n    color: GOLD,\n  });\n\n  // Render all SVGs in parallel\n  await Promise.all([\n    equation1.waitForRender(),\n    equation2.waitForRender(),\n    multiPart.waitForRender(),\n    equation3.waitForRender(),\n    matrix.waitForRender(),\n    pythagoras.waitForRender(),\n    pythagorasExpanded.waitForRender(),\n    scalingEq.waitForRender(),\n    shiftingEq.waitForRender(),\n    rotatingEq.waitForRender(),\n    textBefore.waitForRender(),\n    textAfter.waitForRender(),\n  ]);\n\n  // 1. Create animation - stroke-draw reveal (the main feature)\n  await scene.play(new Create(equation1, { duration: 3 }));\n  await scene.wait(1);\n  await scene.play(new FadeOut(equation1));\n\n  // 2. DrawBorderThenFill animation\n  await scene.play(new DrawBorderThenFill(equation2, { duration: 2 }));\n  await scene.wait(1);\n  await scene.play(new FadeOut(equation2));\n\n  // 3. Multi-part with per-part coloring\n  multiPart.getPart(0).setColor(RED);\n  multiPart.getPart(1).setColor(WHITE);\n  multiPart.getPart(2).setColor(BLUE);\n\n  await scene.play(new FadeIn(multiPart));\n  await scene.wait(2);\n  await scene.play(new FadeOut(multiPart));\n\n  // 4. Another Create with a summation\n  await scene.play(new Create(equation3, { duration: 2 }));\n  await scene.wait(2);\n  await scene.play(new FadeOut(equation3));\n\n  // 5. 2x2 matrix with subscript indices\n  await scene.play(new Create(matrix, { duration: 2 }));\n  await scene.wait(2);\n  await scene.play(new FadeOut(matrix));\n\n  // 6. Transform one equation into another\n  await scene.play(new FadeIn(pythagoras));\n  await scene.wait(1);\n  await scene.play(new Transform(pythagoras, pythagorasExpanded, { duration: 2 }));\n  await scene.wait(1);\n  // After Transform, source (pythagoras) visually becomes target, target is removed\n  await scene.play(new FadeOut(pythagoras));\n\n  // 7. Scale animation\n  await scene.play(new FadeIn(scalingEq));\n  await scene.wait(0.5);\n  await scene.play(new Scale(scalingEq, { scaleFactor: 2, duration: 1.5 }));\n  await scene.wait(0.5);\n  await scene.play(new Scale(scalingEq, { scaleFactor: 0.5, duration: 1 }));\n  await scene.wait(0.5);\n  await scene.play(new FadeOut(scalingEq));\n\n  // 8. Shift animation\n  await scene.play(new FadeIn(shiftingEq));\n  await scene.wait(0.5);\n  await scene.play(new Shift(shiftingEq, { direction: [3, 0, 0], duration: 1 }));\n  await scene.wait(0.5);\n  await scene.play(new Shift(shiftingEq, { direction: [-6, 0, 0], duration: 1 }));\n  await scene.wait(0.5);\n  await scene.play(new Shift(shiftingEq, { direction: [3, 2, 0], duration: 1 }));\n  await scene.wait(0.5);\n  await scene.play(new FadeOut(shiftingEq));\n\n  // 9. Rotate animation\n  await scene.play(new FadeIn(rotatingEq));\n  await scene.wait(0.5);\n  await scene.play(new Rotate(rotatingEq, { angle: Math.PI * 2, duration: 2 }));\n  await scene.wait(0.5);\n  await scene.play(new FadeOut(rotatingEq));\n\n  // 10. ReplacementTransform - change text\n  await scene.play(new FadeIn(textBefore));\n  await scene.wait(1);\n  await scene.play(new Transform(textBefore, textAfter, { duration: 1.5 }));\n  await scene.wait(1);\n  // After Transform, textBefore is morphed to look like textAfter\n  await scene.play(new FadeOut(textBefore));\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait mathtexSvgDemo(scene);\n' },
  { id: 'official-mathtex_to_text_transform', title: 'Mathtex To Text Transform', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const label = new MathTex({ latex: \'\\\\text{Text}\', color: TEAL });\n  await label.waitForRender();\n  scene.add(label);\n\n  const text = new Text({\n    text: \'the brown fox\',\n    color: ORANGE,\n    fontUrl: \'./fonts/KaTeX_Main-Regular.ttf\',\n  });\n  await text.loadGlyphs();\n  await scene.play(new Transform(label, text, { duration: 1 }));\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-mathtex_zero_scale_morph', title: 'Mathtex Zero Scale Morph', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '// Regression demo for issue #310: Transforming a small MathTex("0") into a\n// big MathTex("0") used to render rectangular artefacts because the\n// linearity test in VMobjectGeometry.isNearlyLinear used an absolute\n// threshold and was not scale-invariant.\n\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nasync function run() {\n  scene.clear();\n\n  const small = new MathTex({ latex: \'0\', color: WHITE, fillOpacity: 1, fontSize: 24 });\n  const big = new MathTex({ latex: \'0\', color: WHITE, fillOpacity: 1, fontSize: 240 });\n  await Promise.all([small.waitForRender(), big.waitForRender()]);\n\n  scene.add(small);\n  await scene.play(new Transform(small, big, { duration: 2 }));\n  await new Promise((r) => setTimeout(r, 600));\n  await scene.play(new Transform(small, small.copy(), { duration: 0 }));\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })?.addEventListener(\'click\', async () => {\n\n  const btn = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }) | null;\n  if (btn) btn.disabled = true;\n  await run();\n\n  if (btn) btn.disabled = false;\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })?.addEventListener(\'click\', () => {\n  scene.clear();\n});\n' },
  { id: 'official-moving_angle', title: 'Moving Angle', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '// Converted from Python Manim → ManimWeb TypeScript\n// Review and adjust as needed — automated conversion is approximate.\n\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nasync function movingAngle(scene) {\n  scene.clear();\n\n  const rotation_center = LEFT;\n\n  const theta_tracker = new ValueTracker(110);\n  const line1 = new Line({ start: LEFT, end: RIGHT });\n  const line_moving = new Line({ start: LEFT, end: RIGHT });\n  const line_ref = line_moving.copy();\n  line_moving.rotate(theta_tracker.getValue() * (Math.PI / 180), { aboutPoint: rotation_center });\n  const a = new Angle({ line1: line1, line2: line_moving }, { radius: 0.5, otherAngle: false });\n  const tex = new MathTexImage({ latex: \'\\\\theta\', color: WHITE });\n  await tex.waitForRender();\n  tex.moveTo(\n    new Angle(\n      { line1: line1, line2: line_moving },\n      { radius: 0.5 + 3 * SMALL_BUFF, otherAngle: false },\n    ).pointFromProportion(0.5),\n  );\n\n  scene.add(line1, line_moving, a, tex);\n  await scene.wait(1);\n\n  line_moving.addUpdater((x) => {\n    x.become(line_ref.copy());\n    x.rotate(theta_tracker.getValue() * (Math.PI / 180), { aboutPoint: rotation_center });\n  });\n\n  a.addUpdater((x) =>\n    x.become(new Angle({ line1: line1, line2: line_moving }, { radius: 0.5, otherAngle: false })),\n  );\n  tex.addUpdater((x) =>\n    x.moveTo(\n      new Angle(\n        { line1: line1, line2: line_moving },\n        { radius: 0.5 + 3 * SMALL_BUFF, otherAngle: false },\n      ).pointFromProportion(0.5),\n    ),\n  );\n\n  await scene.play(theta_tracker.animateTo(40));\n  await scene.play(theta_tracker.animateTo(theta_tracker.getValue() + 140));\n  await scene.play(new FadeToColor(tex, { color: RED, duration: 0.5 }));\n  await scene.play(theta_tracker.animateTo(350));\n\n  await scene.wait(1);\n}\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait movingAngle(scene);\n' },
  { id: 'official-moving_around', title: 'Moving Around', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const square = new Square({ color: BLUE, fillOpacity: 1 });\n\n  await scene.play(new Shift(square, { direction: LEFT }));\n\n  square.generateTarget();\n  square.targetCopy.setFill(ORANGE);\n  await scene.play(new MoveToTarget(square));\n\n  await scene.play(new Scale(square, { scaleFactor: 0.3 }));\n\n  await scene.play(new Rotate(square, { angle: 0.4 }));\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-moving_dots', title: 'Moving Dots', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  try {\n    scene.clear();\n\n    const d1 = new Dot({ color: BLUE });\n    const d2 = new Dot({ color: GREEN });\n    new VGroup(d1, d2).arrange(RIGHT, 1);\n    const l1 = new Line({ start: d1.getCenter(), end: d2.getCenter() }).setColor(RED);\n    const x = new ValueTracker(0);\n    const y = new ValueTracker(0);\n    d1.addUpdater((z) => z.setX(x.getValue()));\n    d2.addUpdater((z) => z.setY(y.getValue()));\n    l1.addUpdater((z) => z.become(new Line({ start: d1.getCenter(), end: d2.getCenter() })));\n    scene.add(d1, d2, l1);\n    await scene.play(x.animateTo(5));\n    await scene.play(y.animateTo(4));\n    await scene.wait();\n  } catch (e) {\n    console.error(\'ERROR:\', e.message, e.stack);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-moving_frame_box', title: 'Moving Frame Box', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: "// Converted from Python Manim → ManimWeb TypeScript\n// Review and adjust as needed — automated conversion is approximate.\n\n\n\nasync function movingFrameBox(scene) {\n  const text = new MathTexImage({\n    latex: ['\\\\frac{d}{dx}f(x)g(x)=', 'f(x)\\\\frac{d}{dx}g(x)', '+', 'g(x)\\\\frac{d}{dx}f(x)'],\n  });\n  await text.waitForRender();\n  await scene.play(new Write(text));\n  const framebox1 = new SurroundingRectangle(text.getPart(1), { buff: 0.1 });\n  const framebox2 = new SurroundingRectangle(text.getPart(3), { buff: 0.1 });\n  await scene.play(new Create(framebox1));\n  await scene.wait();\n  await scene.play(new ReplacementTransform(framebox1, framebox2));\n  await scene.wait();\n}\n\nconst container = document.getElementById('container');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: '#000000',\n});\n\nmovingFrameBox(scene);\n\n// Embed mode: hide controls, auto-play, loop\n\nawait movingFrameBox(scene);\n" },
  { id: 'official-moving_group_to_destination', title: 'Moving Group To Destination', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const group = new VGroup(\n    new Dot({ point: LEFT }),\n    new Dot({ point: ORIGIN }),\n    new Dot({ point: RIGHT, color: RED }),\n    new Dot({ point: scaleVec(2, RIGHT) }),\n  ).scale(1.4);\n\n  const dest = new Dot({ point: [4, 3, 0], color: YELLOW });\n\n  scene.add(group, dest);\n\n  await scene.play(\n    new Shift(group, {\n      direction: subVec(dest.getCenter(), group.get(2).getCenter()),\n    }),\n  );\n  await scene.wait(0.5);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-opening_manim', title: 'Opening Manim', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst FONT_URL = \'./fonts/KaTeX_Main-Regular.ttf\';\n\nconst container = document.getElementById(\'container\');\nconst status = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 });\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nfunction log(msg) {\n  status.textContent = msg;\n  console.log(\'[OpeningManim]\', msg);\n}\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n  scene.clear();\n\n  try {\n    // Part 1: Title and equation (Write title, FadeIn equation from below)\n    log(\'Part 1: Title and equation...\');\n    const title = new Text({\n      text: \'This is some LaTeX\',\n      fontSize: 48,\n      color: WHITE,\n      fontUrl: FONT_URL,\n    });\n    const basel = new MathTexImage({\n      latex: \'\\\\sum_{n=1}^\\\\infty \\\\frac{1}{n^2} = \\\\frac{\\\\pi^2}{6}\',\n    });\n    await basel.waitForRender?.();\n\n    new VGroup(title, basel).arrange(DOWN);\n    scene.add(title, basel);\n    await scene.play(new FadeIn(title), new FadeIn(basel, { shift: DOWN }));\n    await scene.wait(1);\n\n    // Part 2: Transform title to UL corner, fade out equation downward\n    log(\'Part 2: Transform title...\');\n    const transformTitle = new Text({\n      text: \'That was a transform\',\n      fontSize: 48,\n      color: WHITE,\n      fontUrl: FONT_URL,\n    });\n    await transformTitle.loadGlyphs();\n    transformTitle.toCorner(UL);\n    await scene.play(new Transform(title, transformTitle), new FadeOut(basel, { shift: DOWN }));\n    await scene.wait(1);\n\n    // Part 3: Number plane grid with title\n    log(\'Part 3: Number plane grid...\');\n    const grid = new NumberPlane();\n    const gridTitle = new Text({\n      text: \'This is a grid\',\n      fontSize: 72,\n      color: WHITE,\n      fontUrl: FONT_URL,\n    });\n    await gridTitle.loadGlyphs();\n    gridTitle.moveTo(transformTitle);\n\n    await scene.play(\n      new FadeOut(title),\n      new FadeIn(gridTitle, { shift: UP }),\n      new Create(grid, { duration: 3, lagRatio: 0.1 }),\n    );\n    await scene.wait(1);\n\n    // Part 4: Non-linear grid transform (sin warp)\n    log(\'Part 4: Non-linear grid transform...\');\n    const gridTransformTitle = new Text({\n      text: \'That was a non-linear function\\napplied to the grid\',\n      fontSize: 48,\n      color: WHITE,\n      fontUrl: FONT_URL,\n    });\n    await gridTransformTitle.loadGlyphs();\n    gridTransformTitle.moveTo(gridTitle, UL);\n    grid.prepareForNonlinearTransform();\n    await scene.play(\n      new ApplyPointwiseFunction(\n        grid,\n        (p) => {\n          return [p[0] + Math.sin(p[1]), p[1] + Math.sin(p[0]), p[2]];\n        },\n        { duration: 3 },\n      ),\n    );\n    await scene.wait(1);\n\n    // Part 5: Transform grid title to explain what happened\n    log(\'Part 5: Grid transform title...\');\n    await scene.play(new Transform(gridTitle, gridTransformTitle));\n    await scene.wait(1);\n\n    log(\'Done!\');\n  } catch (err) {\n    log(\'Error: \' + err.message);\n    console.error(err);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n// Auto-play on load\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).click();\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-picture_in_picture_camera', title: 'Picture In Picture Camera', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#1a1a2e\',\n});\n\nasync function pictureInPictureExample(scene: Scene) {\n  // Main camera: wide overview of the whole scene.\n  const mainCamera = new Camera2D({ frameWidth: 14, frameHeight: 8, position: [0, 0, 10] });\n\n  // PiP camera: zoomed-in inset that follows a moving target. `contain`\n  // keeps the requested 4×4 frame fully visible inside the PiP square\n  // viewport instead of letting MultiCamera stretch its width.\n  const pipCamera = new Camera2D({\n    frameWidth: 4,\n    frameHeight: 4,\n    position: [0, 0, 10],\n    aspectMode: \'contain\',\n  });\n\n  const mc = new MultiCamera();\n  mc.setupPictureInPicture(mainCamera, pipCamera, \'top-right\', 0.3);\n  // Index 0 is the main viewport, index 1 is the PiP inset (per\n  // setupPictureInPicture\'s add order). Highlight the PiP so users can\n  // see where the inset camera is framing.\n  mc.setViewportBorder(1, { borderColor: \'#ffd54f\', borderWidth: 3 });\n  scene.useMultiCamera(mc);\n\n  const square = new Square({ sideLength: 1.5, color: PURPLE, strokeWidth: 4 });\n  const triangle = new Triangle({ color: GREEN, strokeWidth: 4 });\n  triangle.shift([-4, 1, 0]);\n  const orbiter = new Circle({ radius: 0.35, color: YELLOW, strokeWidth: 4 });\n\n  // ValueTracker drives the orbiter; the PiP camera follows it via updater.\n  const t = new ValueTracker(0);\n  orbiter.addUpdater(() => {\n    const a = t.getValue();\n    orbiter.moveTo([3 * Math.cos(a), 2 * Math.sin(a), 0]);\n    const p = orbiter.getCenter();\n    pipCamera.position.set(p[0], p[1], 10);\n  });\n  scene.add(t, square, triangle, orbiter);\n\n  await scene.play(new Create(square));\n  await scene.play(new Create(triangle));\n  await scene.play(new Create(orbiter));\n  await scene.play(t.animateTo(Math.PI * 4, { duration: 4 }));\n  await scene.wait(0.5);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.useMultiCamera(null);\n  scene.clear();\n});\n\nawait pictureInPictureExample(scene);\n' },
  { id: 'official-point_moving_on_shapes', title: 'Point Moving On Shapes', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const circle = new Circle({ radius: 1, color: BLUE });\n  const dot = new Dot();\n  const dot2 = dot.copy().shift(RIGHT);\n  scene.add(dot);\n\n  const line = new Line({ start: [3, 0, 0], end: [5, 0, 0] });\n  scene.add(line);\n\n  await scene.play(new GrowFromCenter(circle));\n  await scene.play(new Transform(dot, dot2));\n  await scene.play(new MoveAlongPath(dot, { path: circle, duration: 2, rateFunc: linear }));\n  await scene.play(new Rotating(dot, { aboutPoint: [2, 0, 0], duration: 1.5 }));\n  await scene.wait();\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-point_with_trace', title: 'Point With Trace', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const path = new VMobject();\n  path.fillOpacity = 0;\n  const dot = new Dot();\n  path.setPointsAsCorners([dot.getCenter(), dot.getCenter()]);\n\n  const updatePath = (pathMob) => {\n    const previousPath = pathMob.copy();\n    previousPath.addPointsAsCorners([dot.getCenter()]);\n    pathMob.become(previousPath);\n  };\n  path.addUpdater(updatePath);\n\n  scene.add(path, dot);\n\n  await scene.play(new Rotating(dot, { angle: Math.PI, aboutPoint: RIGHT, duration: 2 }));\n  await scene.wait();\n  await scene.play(new Shift(dot, { direction: UP }));\n  await scene.play(new Shift(dot, { direction: LEFT }));\n  await scene.wait();\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-polygon_on_axes', title: 'Polygon On Axes', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '// Converted from Python Manim → ManimWeb TypeScript\n// Review and adjust as needed — automated conversion is approximate.\n\n\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 854,\n  height: 480,\n  backgroundColor: BLACK,\n});\n\nfunction getRectangleCorners(bottomLeft, topRight) {\n  return [\n    [topRight[0], topRight[1]],\n    [bottomLeft[0], topRight[1]],\n    [bottomLeft[0], bottomLeft[1]],\n    [topRight[0], bottomLeft[1]],\n  ];\n}\n\nasync function polygonOnAxes(scene) {\n  const ax = new Axes({\n    xRange: [0, 10],\n    yRange: [0, 10],\n    xLength: 6,\n    yLength: 6,\n    tips: false,\n  });\n\n  const t = new ValueTracker(5);\n  const k = 25;\n\n  const graph = ax.plot((x) => k / x, { color: YELLOW_D, xRange: [k / 10, 10.0], numSamples: 750 });\n\n  function makeRectangle() {\n    const corners = getRectangleCorners([0, 0], [t.getValue(), k / t.getValue()]);\n    const vertices = corners.map(([x, y]) => ax.c2p(x, y));\n    const p = new Polygon({ vertices, strokeWidth: 1, color: YELLOW_B, fillOpacity: 0.5 });\n    p.fillColor = BLUE;\n    return p;\n  }\n\n  const polygon = makeRectangle();\n  polygon.addUpdater(() => {\n    polygon.become(makeRectangle());\n  });\n\n  const dot = new Dot();\n  dot.addUpdater(() => dot.moveTo(ax.c2p(t.getValue(), k / t.getValue())));\n\n  scene.add(ax, graph);\n  await scene.play(new Create(polygon));\n  scene.add(dot);\n  await scene.play(t.animateTo(10));\n  await scene.play(t.animateTo(k / 10));\n  await scene.play(t.animateTo(5));\n}\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait polygonOnAxes(scene);\n' },
  { id: 'official-quad_view_camera', title: 'Quad View Camera', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#1a1a2e\',\n});\n\nasync function quadViewExample(scene: Scene) {\n  // Four Camera2D instances framing the same scene at different positions\n  // and zoom levels — a "control room" layout. setupQuadView() places them\n  // in viewport order [top-left, top-right, bottom-left, bottom-right] on\n  // the canvas, so the variable names below describe the on-screen pane,\n  // not the world region the camera looks at.\n  // `contain` keeps each pane\'s requested frame fully visible in its\n  // quad-cell viewport instead of letting MultiCamera stretch widths.\n  const overviewPane = new Camera2D({\n    frameWidth: 14,\n    frameHeight: 8,\n    position: [0, 0, 10],\n    aspectMode: \'contain\',\n  });\n  const circlePane = new Camera2D({\n    frameWidth: 4,\n    frameHeight: 4,\n    position: [-3, 2, 10],\n    aspectMode: \'contain\',\n  });\n  const squarePane = new Camera2D({\n    frameWidth: 4,\n    frameHeight: 4,\n    position: [3, 2, 10],\n    aspectMode: \'contain\',\n  });\n  const trianglePane = new Camera2D({\n    frameWidth: 6,\n    frameHeight: 4,\n    position: [0, -2, 10],\n    aspectMode: \'contain\',\n  });\n\n  const mc = new MultiCamera();\n  mc.setupQuadView([overviewPane, circlePane, squarePane, trianglePane]);\n  // Highlight every cell so the four-pane grid is obvious. Different\n  // tints make the close-up panes easy to tell apart at a glance.\n  mc.setViewportBorder(0, { borderColor: \'#888888\', borderWidth: 2 });\n  mc.setViewportBorder(1, { borderColor: \'#ef5350\', borderWidth: 2 });\n  mc.setViewportBorder(2, { borderColor: \'#42a5f5\', borderWidth: 2 });\n  mc.setViewportBorder(3, { borderColor: \'#66bb6a\', borderWidth: 2 });\n  scene.useMultiCamera(mc);\n\n  const circle = new Circle({ radius: 0.9, color: RED, strokeWidth: 4 });\n  circle.shift([-3, 2, 0]);\n  const square = new Square({ sideLength: 1.4, color: BLUE, strokeWidth: 4 });\n  square.shift([3, 2, 0]);\n  const triangle = new Triangle({ color: GREEN, strokeWidth: 4 });\n  triangle.shift([0, -2, 0]);\n  const ball = new Circle({ radius: 0.25, color: YELLOW, strokeWidth: 3 });\n\n  // Animate a "ball" bouncing between the three regions; each quad-view\n  // close-up shows the ball passing through its quadrant in detail.\n  const t = new ValueTracker(0);\n  ball.addUpdater(() => {\n    const a = t.getValue();\n    const path: Array<[number, number]> = [\n      [-3, 2],\n      [3, 2],\n      [0, -2],\n      [-3, 2],\n    ];\n    const seg = Math.floor(a) % (path.length - 1);\n    const f = a - Math.floor(a);\n    const [x0, y0] = path[seg];\n    const [x1, y1] = path[seg + 1];\n    ball.moveTo([x0 + (x1 - x0) * f, y0 + (y1 - y0) * f, 0]);\n  });\n  scene.add(t);\n\n  // Highlight marker that stays at world origin so the overview pane has\n  // a visible reference point too.\n  const marker = new Circle({ radius: 0.12, color: ORANGE, strokeWidth: 2 });\n  scene.add(marker);\n\n  scene.add(circle, square, triangle, ball);\n  await scene.play(new Create(circle));\n  await scene.play(new Create(square));\n  await scene.play(new Create(triangle));\n  await scene.play(new Create(ball));\n  await scene.play(t.animateTo(3, { duration: 4 }));\n  await scene.wait(0.5);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.useMultiCamera(null);\n  scene.clear();\n});\n\nawait quadViewExample(scene);\n' },
  { id: 'official-rate_functions_comparison', title: 'Rate Functions Comparison', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n// Rate functions to compare, each with a label and color\nconst rateFunctions: Array<{\n  name: string;\n  rateFunc: (t: number) => number;\n  color: string;\n}> = [\n  { name: \'smooth\', rateFunc: smooth, color: BLUE },\n  { name: \'runningStart\', rateFunc: runningStart(-0.2), color: RED },\n  { name: \'thereAndBackWithPause\', rateFunc: thereAndBackWithPause(), color: GREEN },\n  { name: \'lingering\', rateFunc: lingering, color: YELLOW },\n  { name: \'exponentialDecay\', rateFunc: exponentialDecay(), color: PURPLE },\n  { name: \'slowInto\', rateFunc: slowInto, color: ORANGE },\n];\n\nconst ROW_COUNT = rateFunctions.length;\nconst TOP_Y = 2.4;\nconst ROW_SPACING = 0.85;\nconst START_X = -1.5;\nconst SHIFT_DISTANCE = 5.5;\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const dots: Dot[] = [];\n  const shiftDirection = scaleVec(SHIFT_DISTANCE, RIGHT) as [number, number, number];\n\n  for (let i = 0; i < ROW_COUNT; i++) {\n    const y = TOP_Y - i * ROW_SPACING;\n    const { name, color } = rateFunctions[i];\n\n    // Track line (faint guide)\n    const trackLine = new Line({\n      start: [START_X, y, 0],\n      end: [START_X + SHIFT_DISTANCE, y, 0],\n      color: \'#333333\',\n      strokeWidth: 1,\n    });\n\n    // Label on the left, right-edge aligned just before track start\n    const label = new Text({\n      text: name,\n      fontSize: 28,\n      color: WHITE,\n    });\n    label.nextTo(trackLine, LEFT, 0.2);\n\n    // Dot at the start position\n    const dot = new Dot({\n      point: [START_X, y, 0],\n      radius: 0.1,\n      color,\n    });\n\n    scene.add(label, trackLine, dot);\n    dots.push(dot);\n  }\n\n  // Build simultaneous shift animations with different rate functions\n  const animations = dots.map(\n    (dot, i) =>\n      new Shift(dot, {\n        direction: shiftDirection,\n        duration: 3,\n        rateFunc: rateFunctions[i].rateFunc,\n      }),\n  );\n\n  await scene.play(new AnimationGroup(animations));\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-replacement_transform', title: 'Replacement Transform', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\') as HTMLElement;\nconst status = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 });\nconst scene = new Scene(container, { width: 800, height: 450, backgroundColor: BLACK });\n\nlet busy = false;\n\nfunction log(msg: string) {\n  status.textContent = `${msg}\\n${status.textContent}`.slice(0, 4000);\n}\n\nfunction describe(label: string) {\n  const names: string[] = [];\n  for (const m of scene.mobjects) {\n    names.push((m as { constructor: { name: string } }).constructor.name);\n  }\n  log(`${label}: scene has ${names.length} mobjects -> [${names.join(\', \')}]`);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', async () => {\n  if (busy) return;\n  busy = true;\n  (({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })).disabled = true;\n  scene.clear();\n\n  // Plain Transform: morphs visuals but the SOURCE stays in the scene.\n  const a = new Circle({ radius: 1.4, color: RED, fillOpacity: 0.9, strokeWidth: 6 }).shift([\n    -3, 0, 0,\n  ]);\n  const aTarget = new Square({\n    sideLength: 2.2,\n    color: GREEN,\n    fillOpacity: 0.9,\n    strokeWidth: 6,\n  }).shift([-3, 0, 0]);\n  scene.add(a);\n  describe(\'before Transform\');\n  await scene.play(new Transform(a, aTarget, { duration: 1.2 }));\n  describe(\'after  Transform     \');\n\n  await scene.wait(0.6);\n\n  // ReplacementTransform: source removed, target added (issue #308 fix).\n  const b = new Circle({ radius: 1.4, color: BLUE, fillOpacity: 0.9, strokeWidth: 6 }).shift([\n    3, 0, 0,\n  ]);\n  const bTarget = new Square({\n    sideLength: 2.2,\n    color: YELLOW,\n    fillOpacity: 0.9,\n    strokeWidth: 6,\n  }).shift([3, 0, 0]);\n  scene.add(b);\n  describe(\'before ReplacementTx\');\n  await scene.play(new ReplacementTransform(b, bTarget, { duration: 1.2 }));\n  describe(\'after  ReplacementTx\');\n\n  await scene.wait(0.8);\n\n  busy = false;\n  (({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })).disabled = false;\n});\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 })!.addEventListener(\'click\', () => {\n  scene.clear();\n  status.textContent = \'cleared.\';\n});\n' },
  { id: 'official-rotation_updater', title: 'Rotation Updater', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  try {\n    scene.clear();\n\n    const updaterForth = (mobj, dt) => {\n      mobj.rotateAboutOrigin(dt);\n    };\n    const updaterBack = (mobj, dt) => {\n      mobj.rotateAboutOrigin(-dt);\n    };\n    const lineReference = new Line({ start: ORIGIN, end: LEFT }).setColor(WHITE);\n    const lineMoving = new Line({ start: ORIGIN, end: LEFT }).setColor(YELLOW);\n    lineMoving.addUpdater(updaterForth);\n    scene.add(lineReference, lineMoving);\n    await scene.wait(2);\n    lineMoving.removeUpdater(updaterForth);\n    lineMoving.addUpdater(updaterBack);\n    await scene.wait(2);\n    lineMoving.removeUpdater(updaterBack);\n    await scene.wait(0.5);\n  } catch (e) {\n    console.error(\'ERROR:\', e.message, e.stack);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-sin_cos_plot', title: 'Sin Cos Plot', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '// Converted from Python Manim → ManimWeb TypeScript\n// Review and adjust as needed — automated conversion is approximate.\n\n\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 854,\n  height: 480,\n  backgroundColor: BLACK,\n});\n\nasync function sinAndCosFunctionPlot(scene) {\n  const axes = new Axes({\n    xRange: [-10, 10.3, 1],\n    yRange: [-1.5, 1.5, 1],\n    xLength: 10,\n    axisConfig: { color: GREEN },\n    xAxisConfig: {\n      numbersToInclude: [-10, -8, -6, -4, -2, 0, 2, 4, 6, 8, 10],\n      numbersWithElongatedTicks: [-10, -8, -6, -4, -2, 0, 2, 4, 6, 8, 10],\n    },\n    tips: false,\n  });\n  const axesLabels = axes.getAxisLabels();\n  const sinGraph = axes.plot((x) => Math.sin(x), { color: BLUE });\n  const cosGraph = axes.plot((x) => Math.cos(x), { color: RED });\n\n  const sinLabel = axes.getGraphLabel(sinGraph, \'\\\\sin(x)\', {\n    xVal: -10,\n    direction: scaleVec(0.5, UP),\n  });\n  const cosLabel = axes.getGraphLabel(cosGraph, { label: \'\\\\cos(x)\' });\n\n  const vertLine = axes.getVerticalLine(axes.i2gp(2 * Math.PI, cosGraph), {\n    color: YELLOW,\n    lineFunc: Line,\n  });\n  const lineLabel = axes.getGraphLabel(cosGraph, \'x=2\\\\pi\', {\n    xVal: 2 * Math.PI,\n    direction: UR,\n    color: WHITE,\n  });\n\n  const plot = new VGroup(axes, sinGraph, cosGraph, vertLine);\n  const labels = new VGroup(axesLabels, sinLabel, cosLabel, lineLabel);\n  scene.add(plot, labels);\n}\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait sinAndCosFunctionPlot(scene);\n' },
  { id: 'official-sine_curve_unit_circle', title: 'Sine Curve Unit Circle', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst TAU = 2 * Math.PI;\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  try {\n    scene.clear();\n\n    // --- Axes ---\n    const xAxis = new Line({ start: [-6, 0, 0], end: [6, 0, 0] });\n    const yAxis = new Line({ start: [-4, -2, 0], end: [-4, 2, 0] });\n    scene.add(xAxis, yAxis);\n\n    // --- X labels ---\n    const xLabels = [\n      new MathTexImage({ latex: \'\\\\pi\' }),\n      new MathTexImage({ latex: \'2\\\\pi\' }),\n      new MathTexImage({ latex: \'3\\\\pi\' }),\n      new MathTexImage({ latex: \'4\\\\pi\' }),\n    ];\n    for (let i = 0; i < xLabels.length; i++) {\n      xLabels[i].nextTo([-1 + 2 * i, 0, 0], DOWN, 0.4);\n      scene.add(xLabels[i]);\n    }\n\n    const originPoint = [-4, 0, 0];\n    const curveStart = [-3, 0, 0];\n\n    // --- Circle ---\n    const circle = new Circle({ radius: 1, center: originPoint, color: RED });\n    scene.add(circle);\n\n    // --- Dot orbiting the circle ---\n    let tOffset = 0;\n    const rate = 0.25;\n\n    const dot = new Dot({\n      radius: 0.08,\n      color: YELLOW,\n      point: circle.pointAtAngle(0),\n    });\n\n    const goAroundCircle = (_mob, dt) => {\n      tOffset += dt * rate;\n      dot.moveTo(circle.pointAtAngle((tOffset % 1) * TAU));\n    };\n    dot.addUpdater(goAroundCircle);\n\n    // --- Line from origin to dot (always_redraw equivalent) ---\n    const originToCircleLine = new Line({\n      start: originPoint,\n      end: dot.getPoint(),\n      color: BLUE,\n    });\n    originToCircleLine.addUpdater(() => {\n      originToCircleLine.setStart(originPoint);\n      originToCircleLine.setEnd(dot.getPoint());\n    });\n\n    // --- Line from dot to curve (always_redraw equivalent) ---\n    const dotToCurveLine = new Line({\n      start: dot.getPoint(),\n      end: dot.getPoint(),\n      color: YELLOW_A,\n      strokeWidth: 2,\n    });\n    dotToCurveLine.addUpdater(() => {\n      const x = curveStart[0] + tOffset * 4;\n      const y = dot.getPoint()[1];\n      dotToCurveLine.setStart(dot.getPoint());\n      dotToCurveLine.setEnd([x, y, 0]);\n    });\n\n    // --- Growing sine curve ---\n    const curve = new VGroup();\n    curve.add(new Line({ start: curveStart, end: curveStart, color: YELLOW_D }));\n    let lastEnd = [...curveStart];\n\n    curve.addUpdater(() => {\n      const x = curveStart[0] + tOffset * 4;\n      const y = dot.getPoint()[1];\n      const newLine = new Line({\n        start: lastEnd,\n        end: [x, y, 0],\n        color: YELLOW_D,\n      });\n      curve.add(newLine);\n      lastEnd = [x, y, 0];\n    });\n\n    // Add in order: dot first so tOffset/position updates before lines read it\n    scene.add(dot, originToCircleLine, dotToCurveLine, curve);\n\n    await scene.wait(8.5);\n\n    dot.removeUpdater(goAroundCircle);\n  } catch (e) {\n    console.error(\'ERROR:\', e.message, e.stack);\n  }\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-split_screen_camera', title: 'Split Screen Camera', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#1a1a2e\',\n});\n\nasync function splitScreenCameraExample(scene: Scene) {\n  // Two independent Camera2D instances framing the same scene at\n  // different zoom levels. With `aspectMode: \'contain\'` the per-camera\n  // frameWidth/frameHeight is honoured at render time (the viewport\n  // letterboxes if it doesn\'t match), so the zoom intent — wide\n  // overview on the left, tight zoom on the right — actually shows up\n  // on screen.\n  const leftCamera = new Camera2D({\n    frameWidth: 14,\n    frameHeight: 8,\n    position: [-3, 0, 10],\n    aspectMode: \'contain\',\n  });\n  const rightCamera = new Camera2D({\n    frameWidth: 4,\n    frameHeight: 4,\n    position: [3, 0, 10],\n    aspectMode: \'contain\',\n  });\n\n  const split = new SplitScreenCamera({\n    leftCamera,\n    rightCamera,\n    split: \'horizontal\',\n    splitRatio: 0.5,\n  });\n  const mc = split.getMultiCamera();\n  // Draw a thin border around each pane so the split is visible even\n  // when one side renders the scene background edge-to-edge.\n  mc.setViewportBorder(0, { borderColor: \'#888888\', borderWidth: 2 });\n  mc.setViewportBorder(1, { borderColor: \'#888888\', borderWidth: 2 });\n  scene.useMultiCamera(mc);\n\n  const circle = new Circle({ radius: 1, color: RED, strokeWidth: 4 });\n  circle.shift([-3, 0, 0]);\n  const square = new Square({ sideLength: 1.5, color: BLUE, strokeWidth: 4 });\n  square.shift([3, 0, 0]);\n  const marker = new Circle({ radius: 0.15, color: YELLOW, strokeWidth: 3 });\n\n  scene.add(marker);\n  await scene.play(new Create(circle));\n  await scene.play(new Create(square));\n  await scene.wait(0.8);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.useMultiCamera(null);\n  scene.clear();\n});\n\nawait splitScreenCameraExample(scene);\n' },
  { id: 'official-test_write', title: 'Test Write', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst FONT_URL = \'./fonts/KaTeX_Main-Regular.ttf\';\nconst container = document.getElementById(\'container\');\nconst status = ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 });\n\nconst scene = new Scene(container, { width: 800, height: 450, backgroundColor: BLACK });\n\nasync function run() {\n  status.textContent = \'Loading glyphs...\';\n  const text = new Text({\n    text: \'This is some LaTeX\',\n    fontSize: 48,\n    color: WHITE,\n    fontUrl: FONT_URL,\n  });\n  await text.loadGlyphs();\n  scene.add(text);\n  status.textContent = \'Playing Write (5s)...\';\n  await scene.play(new Write(text, { duration: 5 }));\n  status.textContent = \'Done!\';\n}\n\nrun().catch((err) => {\n  status.textContent = \'Error: \' + err.message;\n  console.error(err);\n});\n\n// Embed mode: hide controls, auto-play, loop\n' },
  { id: 'official-text_transform', title: 'Text Transform', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: BLACK,\n});\n\nfunction makeText(text: string, color: string, fontSize: number) {\n  return new Text({\n    text,\n    fontSize,\n    color,\n  });\n}\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = true;\n\n  scene.clear();\n\n  const texts = [\n    makeText(\'This is some text\', WHITE, 40),\n    makeText(\'Text can morph\', TEAL, 40),\n    makeText(\'Text can rotate\', ORANGE, 40),\n    makeText(\'Text can rotate\', ORANGE, 40),\n    makeText(\'Text can rotate\', ORANGE, 40),\n    makeText(\'Text can flip\', TEAL, 40),\n    makeText(\'Text can flip\', TEAL, 40),\n    makeText(\'Text can scale\', ORANGE, 40),\n  ];\n\n  const a = texts[0];\n  a.getThreeObject();\n  await scene.play(new Write(a));\n  await scene.wait(0.4);\n\n  for (let i = 1; i < texts.length; i++) {\n    const target = texts[i];\n    target.moveTo(a.getCenter());\n\n    if (i === 2) target.rotate(20 * (Math.PI / 180));\n    if (i === 3) target.rotate(-40 * (Math.PI / 180));\n    if (i === 5) target.flip();\n    if (i === 7) target.scale(2);\n\n    await scene.play(new Transform(a, target));\n    await scene.wait(0.4);\n  }\n\n  await scene.wait(0.8);\n\n  ({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).disabled = false;\n\n\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n' },
  { id: 'official-three_d_angle', title: 'Three D Angle', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 70 * (Math.PI / 180),\n  theta: -45 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  enableOrbitControls: true,\n  orbitControlsUp: \'z\',\n});\n\nasync function threeDAngle(scene: ThreeDScene) {\n  const axes = new ThreeDAxes({\n    xRange: [-4, 4, 1],\n    yRange: [-4, 4, 1],\n    zRange: [-3, 3, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.3,\n    tipRadius: 0.12,\n    shaftRadius: 0.008,\n  });\n\n  const origin: [number, number, number] = [0, 0, 0];\n  const p1: [number, number, number] = [2, 0, 0];\n  const p2: [number, number, number] = [0, 1.5, 2];\n\n  const line1 = new Line3D({ start: origin, end: p1, color: YELLOW });\n  const line2 = new Line3D({ start: origin, end: p2, color: GREEN });\n\n  const angle = new Angle({ points: [p1, origin, p2] }, { radius: 0.8, color: WHITE });\n\n  scene.add(axes, line1, line2, angle);\n  await scene.wait(Infinity);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n  scene.setCameraOrientation(70 * (Math.PI / 180), -45 * (Math.PI / 180));\n});\n\nawait threeDAngle(scene);\n' },
  { id: 'official-three_d_axes_labels', title: 'Three D Axes Labels', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: "\n\nconst container = document.getElementById('container');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: '#191919',\n  phi: 75 * (Math.PI / 180),\n  theta: -45 * (Math.PI / 180),\n  distance: 24,\n  fov: 35,\n  enableOrbitControls: true,\n  orbitControlsUp: 'z',\n});\n\nconst axes = new ThreeDAxes({\n  xRange: [-5, 5, 1],\n  yRange: [-5, 5, 1],\n  zRange: [-5, 5, 1],\n  showLabels: true,\n  xColor: '#ff6b6b',\n  yColor: '#6bcb77',\n  zColor: '#4d96ff',\n});\n\nscene.add(axes);\n\n// Opt-in Manim CE `shift_onto_screen` equivalent: pull any axis label back\n// toward the origin if it would render outside the viewport.\n// Called after the first render so MathTex sizes exist and the camera matrix\n// is up-to-date.\nawait scene.wait(0.05);\naxes.shiftLabelsOntoScreen(scene.camera3D.getCamera());\n\nawait scene.wait(Infinity);\n" },
  { id: 'official-three_d_axes_labels_shift', title: 'Three D Axes Labels Shift', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: "\n\nasync function makeScene(id: string, shift: boolean) {\n  const container = document.getElementById(id);\n  const scene = new ThreeDScene(container, {\n    width: 500,\n    height: 500,\n    backgroundColor: '#191919',\n    phi: 75 * (Math.PI / 180),\n    theta: -45 * (Math.PI / 180),\n    // Deliberately tight: camera close + narrow FOV so default axis tips clip.\n    distance: 12,\n    fov: 25,\n    orbitControlsUp: 'z',\n  });\n\n  const axes = new ThreeDAxes({\n    xRange: [-5, 5, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-5, 5, 1],\n    showLabels: true,\n    xColor: '#ff6b6b',\n    yColor: '#6bcb77',\n    zColor: '#4d96ff',\n  });\n  scene.add(axes);\n\n  // Let MathTex finish + camera/matrices update.\n  await scene.wait(0.1);\n  if (shift) {\n    axes.shiftLabelsOntoScreen(scene.camera3D.getCamera(), 0.08);\n  }\n\n  // Log positions to console for verification.\n  const cam = scene.camera3D.getCamera();\n  cam.updateMatrixWorld();\n  for (const [name, lbl] of [\n    ['x', axes.getXLabel()],\n    ['y', axes.getYLabel()],\n    ['z', axes.getZLabel()],\n  ] as const) {\n    const world = lbl!.getThreeObject().getWorldPosition(new (await import('three')).Vector3());\n    const ndc = world.clone().project(cam);\n    console.log(\n      `[${shift ? 'SHIFT' : 'BEFORE'}] ${name}: world=(${world.x.toFixed(2)},${world.y.toFixed(2)},${world.z.toFixed(2)}) ndc=(${ndc.x.toFixed(2)},${ndc.y.toFixed(2)})`,\n    );\n  }\n\n  await scene.wait(Infinity);\n}\n\nawait Promise.all([makeScene('c1', false), makeScene('c2', true)]);\n" },
  { id: 'official-three_d_camera_illusion_rotation', title: 'Three D Camera Illusion Rotation', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 75 * (Math.PI / 180),\n  theta: 30 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  orbitControlsUp: \'z\',\n});\n\nasync function threeDCameraIllusionRotation(scene: ThreeDScene) {\n  const axes = new ThreeDAxes({\n    xRange: [-6, 6, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-4, 4, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.3,\n    tipRadius: 0.12,\n    shaftRadius: 0.008,\n  });\n\n  const circle = new Circle({ radius: 1, color: \'#FC6255\' });\n  scene.add(circle, axes);\n\n  // Begin 3D illusion camera rotation (theta rotates at 2 rad/s,\n  // phi oscillates sinusoidally for a wobbling 3D effect)\n  scene.begin3DIllusionCameraRotation(2);\n  await scene.wait(Math.PI / 2);\n\n  // Stop illusion rotation\n  scene.stop3DIllusionCameraRotation();\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n  scene.stop3DIllusionCameraRotation();\n  scene.setCameraOrientation(75 * (Math.PI / 180), 30 * (Math.PI / 180));\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait threeDCameraIllusionRotation(scene);\n' },
  { id: 'official-three_d_camera_rotation', title: 'Three D Camera Rotation', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 75 * (Math.PI / 180),\n  theta: 30 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  orbitControlsUp: \'z\',\n});\n\nasync function threeDCameraRotation(scene: ThreeDScene) {\n  const axes = new ThreeDAxes({\n    xRange: [-6, 6, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-4, 4, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.3,\n    tipRadius: 0.12,\n    shaftRadius: 0.008,\n  });\n\n  const circle = new Circle({ radius: 1, color: \'#FC6255\' });\n  scene.add(circle, axes);\n\n  // Begin ambient camera rotation (theta rotates at 0.1 rad/s)\n  scene.beginAmbientCameraRotation(0.1);\n  await scene.wait(3);\n\n  // Stop rotation and animate camera back to original orientation\n  scene.stopAmbientCameraRotation();\n  await scene.moveCamera({\n    phi: 75 * (Math.PI / 180),\n    theta: 30 * (Math.PI / 180),\n    duration: 1,\n  });\n  await scene.wait(1);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n  scene.stopAmbientCameraRotation();\n  scene.setCameraOrientation(75 * (Math.PI / 180), 30 * (Math.PI / 180));\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait threeDCameraRotation(scene);\n' },
  { id: 'official-three_d_light_source_position', title: 'Three D Light Source Position', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 75 * (Math.PI / 180),\n  theta: 30 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  orbitControlsUp: \'z\',\n});\n\nasync function threeDLightSourcePosition(scene: ThreeDScene) {\n  const axes = new ThreeDAxes({\n    xRange: [-5, 5, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-5, 5, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.2,\n    tipRadius: 0.08,\n    shaftRadius: 0.01,\n  });\n\n  // Checkerboard sphere matching Python Manim\'s Surface(..., checkerboard_colors=[RED_D, RED_E])\n  const sphere = new Surface3D({\n    func: (u: number, v: number) => [\n      1.5 * Math.cos(u) * Math.cos(v),\n      1.5 * Math.cos(u) * Math.sin(v),\n      1.5 * Math.sin(u),\n    ],\n    uRange: [-Math.PI / 2, Math.PI / 2],\n    vRange: [0, 2 * Math.PI],\n    uResolution: 15,\n    vResolution: 32,\n    checkerboardColors: [RED_D, RED_E],\n  });\n\n  // Light from above to match Python Manim\'s default top-lit appearance\n  scene.lighting.removeAll();\n  scene.lighting.addAmbient({ intensity: 0.3 });\n  scene.lighting.addPoint({ position: [0, 5, 0], intensity: 2.5, decay: 0 });\n\n  scene.add(axes);\n  scene.add(sphere);\n\n  await scene.wait(999999);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait threeDLightSourcePosition(scene);\n' },
  { id: 'official-three_d_surface_plot', title: 'Three D Surface Plot', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new ThreeDScene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n  phi: 75 * (Math.PI / 180),\n  theta: -30 * (Math.PI / 180),\n  distance: 20,\n  fov: 30,\n  orbitControlsUp: \'z\',\n});\n\nasync function threeDSurfacePlot(scene: ThreeDScene) {\n  const sigma = 0.4;\n  const mu = [0.0, 0.0];\n\n  // Gaussian surface: Z-up Manim convention — height is along z.\n  const gaussSurface = new Surface3D({\n    func: (u: number, v: number) => {\n      const x = u;\n      const y = v;\n      const dx = x - mu[0];\n      const dy = y - mu[1];\n      const d = Math.sqrt(dx * dx + dy * dy);\n      const z = Math.exp(-(d * d) / (2.0 * sigma * sigma));\n      return [x, y, z];\n    },\n    uRange: [-2, 2],\n    vRange: [-2, 2],\n    uResolution: 24,\n    vResolution: 24,\n    checkerboardColors: [ORANGE, BLUE],\n    opacity: 0.85,\n  });\n\n  // Scale by 2 about origin (matches Python: gauss_plane.scale(2, about_point=ORIGIN)).\n  // Without an explicit aboutPoint, scale() pivots about the surface\'s geometric\n  // center (z≈0.5), which would push the flat base below the z=0 plane.\n  gaussSurface.scale(2, { aboutPoint: [0, 0, 0] });\n\n  const axes = new ThreeDAxes({\n    xRange: [-6, 6, 1],\n    yRange: [-5, 5, 1],\n    zRange: [-4, 4, 1],\n    axisColor: \'#ffffff\',\n    tipLength: 0.3,\n    tipRadius: 0.12,\n    shaftRadius: 0.008,\n  });\n\n  scene.add(axes);\n  scene.add(gaussSurface);\n  await scene.wait(999999);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait threeDSurfacePlot(scene);\n' },
  { id: 'official-vector_arrow', title: 'Vector Arrow', intent: '官方 manim-web 示例(自建 scene/相机,TS 转译后运行;保留官方演示色)', domain: "demo", category: "演示", sceneCode: '\n\nconst container = document.getElementById(\'container\');\nconst scene = new Scene(container, {\n  width: 800,\n  height: 450,\n  backgroundColor: \'#000000\',\n});\n\nasync function vectorArrow(scene: Scene) {\n  const dot = new Dot({ point: ORIGIN, radius: 0.12, color: YELLOW });\n  const arrow = new Arrow({ start: ORIGIN, end: [2, 2, 0] });\n  const numberplane = new NumberPlane();\n  const originText = new Text({ text: \'(0, 0)\' }).nextTo(dot, DOWN);\n  const tipText = new Text({ text: \'(2, 2)\' }).nextTo(arrow.getEnd(), RIGHT);\n  scene.add(numberplane, dot, arrow, originText, tipText);\n}\n\n({ setAttribute(){}, removeAttribute(){}, addEventListener(){}, click(){}, style:{}, disabled:false, textContent:"", value:0 }).addEventListener(\'click\', () => {\n  scene.clear();\n});\n\n// Embed mode: hide controls, auto-play, loop\n\nawait vectorArrow(scene);\n' }
